// make-base64-bundle.js - proof of concept for the base64-payload study.
//
// Wraps an existing JScript file (a dist/ bundle, a --compile output, or any
// script) into a new .js whose entire body is a base64 string plus a decoder:
//
//   cscript.exe bin\launcher.js studies\make-base64-bundle.js --in dist\launcher.js
//   cscript.exe dist\launcher.b64.js yourscript.js
//
// Options:
//   --in <file>    source to wrap        (default: dist\launcher.js)
//   --out <file>   output               (default: <in> with .b64.js)
//   --decoder <n>  "jscript" (default) or "msxml" - see below
//
// The findings this exists to support are in studies/base64-payload.md. Short
// version: it works, it is ~33% bigger than what it wraps, and there is no
// reason to ship it. It is kept as a runnable spike, not as a feature.
//
// Two decoders, because the choice matters more than the wrapper does:
//
//   jscript  A hand-rolled decoder, the same algorithm as libs/base64.js, with
//            no COM at all. Slower - it is an interpreted loop over every
//            character of a 300 KB string - but it depends on nothing. This is
//            the default because it is the one that has actually been run.
//   msxml    MSXML2.DOMDocument with dataType="bin.base64" turns the payload
//            into bytes inside COM, and ADODB.Stream turns those bytes back
//            into text. Native code doing the work; the JScript side is a
//            dozen lines. This is what a productised version should use - but
//            it has not been executed on Windows, so it is not the default.
//
// Run through the launcher (it needs load()).

load("core");
load("polyfills");
load("system");
load("base64");
load("minimist");

// ---------------------------------------------------------------------------
// Arguments
// ---------------------------------------------------------------------------

var argv = [];
for (var a = 0; a < WScript.Arguments.Count(); a++) { argv.push(WScript.Arguments(a)); }

// Argument 0 is this script's own path when it runs through bin/launcher.js.
if (argv.length > 0 && /make-base64-bundle\.js$/i.test(argv[0])) { argv = argv.slice(1); }

var args = minimist(argv, {
    'string': ["in", "out", "decoder"],
    'default': { 'decoder': "jscript" }
});

var fso     = new ActiveXObject("Scripting.FileSystemObject");
var inPath  = fso.GetAbsolutePathName(args['in'] || (ROOT_FOLDER + "dist\\launcher.js"));
var outPath = fso.GetAbsolutePathName(args.out || inPath.replace(/\.js$/i, ".b64.js"));
var decoder = String(args.decoder).toLowerCase();

if (!fso.FileExists(inPath)) {
    log("No such file: " + inPath);
    WScript.Quit(1);
}
if (outPath.toLowerCase() === inPath.toLowerCase()) {
    log("--out would overwrite the source file");
    WScript.Quit(1);
}
if (decoder !== "msxml" && decoder !== "jscript") {
    log("--decoder must be 'msxml' or 'jscript'");
    WScript.Quit(1);
}

// ---------------------------------------------------------------------------
// Encode
// ---------------------------------------------------------------------------

var bytes  = read_binary_file(inPath);
var base64 = base64_encode_bytes(bytes);

// Chunked into an array literal rather than one enormous string literal: a
// single 270 KB line is legal but unreadable, unpleasant for diffs, and pushes
// on limits nobody has documented. Joining an array is cheap and obvious.
var CHUNK = 76;
var chunks = [];
for (var i = 0; i < base64.length; i += CHUNK) {
    chunks.push("'" + base64.substr(i, CHUNK) + "'");
}

// ---------------------------------------------------------------------------
// Emit
// ---------------------------------------------------------------------------

var L = [];

L.push("// " + inPath.slice(inPath.lastIndexOf("\\") + 1) + ", carried as a base64 payload.");
L.push("// Generated by studies/make-base64-bundle.js - a spike, not a shipped feature.");
L.push("// See studies/base64-payload.md.");
L.push("//");
L.push("// Decoder: " + decoder);
L.push("");
L.push("var _payload = [");
L.push(chunks.join(",\n"));
L.push("].join('');");
L.push("");

if (decoder === "msxml") {
    L.push("// MSXML turns base64 into bytes, ADODB.Stream turns bytes into text.");
    L.push("// Both are native code, so the interpreted work is only this wiring.");
    L.push("function _decode_payload(b64) {");
    L.push("    var doc  = new ActiveXObject('MSXML2.DOMDocument.6.0');");
    L.push("    var node = doc.createElement('b64');");
    L.push("    node.dataType = 'bin.base64';");
    L.push("    node.text = b64;");
    L.push("");
    L.push("    var stream = new ActiveXObject('ADODB.Stream');");
    L.push("    stream.Type = 1;                  // adTypeBinary");
    L.push("    stream.Open();");
    L.push("    stream.Write(node.nodeTypedValue);");
    L.push("    stream.Position = 0;");
    L.push("    stream.Type     = 2;              // adTypeText");
    L.push("    stream.CharSet  = 'iso-8859-1';   // one byte in, one character out");
    L.push("    var text = stream.ReadText();");
    L.push("    stream.Close();");
    L.push("    return text;");
    L.push("}");
} else {
    L.push("// The same algorithm as libs/base64.js, inlined: the payload cannot");
    L.push("// depend on a lib that lives inside the payload.");
    L.push("function _decode_payload(b64) {");
    L.push("    var alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';");
    L.push("    var lookup = {};");
    L.push("    for (var k = 0; k < alphabet.length; k++) { lookup[alphabet.charAt(k)] = k; }");
    L.push("");
    L.push("    var clean = b64.replace(/[^A-Za-z0-9+\\/]/g, '');");
    L.push("    var out   = [];");
    L.push("    for (var i = 0; i < clean.length; i += 4) {");
    L.push("        var c0 = lookup[clean.charAt(i)];");
    L.push("        var c1 = lookup[clean.charAt(i + 1)];");
    L.push("        var c2 = lookup[clean.charAt(i + 2)];");
    L.push("        var c3 = lookup[clean.charAt(i + 3)];");
    L.push("");
    L.push("        out.push(String.fromCharCode(((c0 << 2) | (c1 >> 4)) & 0xFF));");
    L.push("        if (typeof c2 !== 'undefined') {");
    L.push("            out.push(String.fromCharCode(((c1 << 4) | (c2 >> 2)) & 0xFF));");
    L.push("        }");
    L.push("        if (typeof c3 !== 'undefined') {");
    L.push("            out.push(String.fromCharCode(((c2 << 6) | c3) & 0xFF));");
    L.push("        }");
    L.push("    }");
    L.push("    return out.join('');");
    L.push("}");
}

L.push("");
L.push("// eval at the top level of a .js run by cscript.exe IS global scope, so the");
L.push("// payload's own top-level vars and function declarations become globals -");
L.push("// exactly as if its source had been pasted here. The cost is error");
L.push("// reporting: everything inside the payload reports as one line of this file.");
L.push("eval(_decode_payload(_payload));");
L.push("");

write_text_to_file(L.join("\r\n"), outPath);

var outSize = fso.GetFile(outPath).Size;
var inSize  = fso.GetFile(inPath).Size;

log("Wrapped:  " + inPath);
log("      ->  " + outPath);
log("  source: " + inSize + " bytes");
log("  base64: " + base64.length + " characters");
log("  output: " + outSize + " bytes (" +
    (outSize / inSize).toFixed(2) + "x the source)");
log("  decoder: " + decoder);
